import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/VECTOR.md","filePath":"manual-en/VECTOR.md","lastUpdated":1785684581000}'),s={name:"manual-en/VECTOR.md"};function n(i,e,c,l,d,m){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h3 id="_11-19-vector" tabindex="-1">11.19 VECTOR <a class="header-anchor" href="#_11-19-vector" aria-label="Permalink to &quot;11.19 VECTOR&quot;">​</a></h3><pre><code>Two possible syntaxes:
        VECTOR vec_name=var_list.
        VECTOR vec_name_list(count [format]).
</code></pre><p><code>VECTOR</code> allows a group of variables to be accessed as if they were consecutive members of an array with a vector(index) notation.</p><p>To make a vector out of a set of existing variables, specify a name for the vector followed by an equals sign (‘=’) and the variables to put in the vector. The variables must be all numeric or all string, and string variables must have the same width.</p><p>To make a vector and create variables at the same time, specify one or more vector names followed by a count in parentheses. This will create variables named <code>vec1</code> through <code>veccount</code>. By default, the new variables are numeric with format F8.2, but an alternate format may be specified inside the parentheses before or after the count and separated from it by white space or a comma. With a string format such as A8, the variables will be string variables; with a numeric format, they will be numeric. Variable names including the suffixes may not exceed 64 characters in length, and none of the variables may exist prior to <code>VECTOR</code>.</p><p>Vectors created with <code>VECTOR</code> disappear after any procedure or procedure-like command is executed. The variables contained in the vectors remain, unless they are scratch variables (see <a href="./Scratch-Variables">Scratch Variables</a>).</p><p>Variables within a vector may be referenced in expressions using <code>vector(index)</code> syntax.</p>`,7)])])}const u=a(s,[["render",n]]);export{p as __pageData,u as default};
